(function() {
  try {
    /**
 * High-Speed M3U Parser optimized for LG webOS TV (webOS 4.64 & 5.0+)
 * - Extracts all EPG URLs from #EXTM3U headers (url-tvg, x-tvg-url, tvg-url, epg-url, comma-separated, .xml & .xml.gz)
 * - Auto-derives Xtream Codes xmltv.php URLs from M3U / stream URLs when header EPG is omitted
 * - Preserves tvg-id, tvg-name, and display name for high-accuracy EPG channel matching
 */
const HEADER_EPG_ATTR_REGEX = /(?:x-tvg-url|url-tvg|tvg-url|epg-url|tvg-epg)\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s"'>]+))/gi;
const XTREAM_GET_REGEX = /^(https?:\/\/[^\/]+)\/get\.php\?([^#]+)/i;
const XTREAM_USER_REGEX = /(?:^|&)username=([^&]+)/i;
const XTREAM_PASS_REGEX = /(?:^|&)password=([^&]+)/i;
const XTREAM_STREAM_REGEX = /^(https?:\/\/[^\/]+)\/(?:live\/)?([a-zA-Z0-9._-]+)\/([a-zA-Z0-9._-]+)\/\d+(?:\.[a-z0-9]+)?$/i;

const GROUP_NAME_MAP = {
  'general': 'ערוצים מרכזיים',
  'news': 'חדשות ואקטואליה',
  'sports': 'ספורט',
  'sport': 'ספורט',
  'entertainment': 'בידור',
  'movies': 'סרטים וסינמה',
  'series': 'סדרות',
  'kids': 'ילדים ונוער',
  'children': 'ילדים ונוער',
  'music': 'מוזיקה',
  'religious': 'מסורת ודת',
  'documentary': 'דוקו וטבע',
  'education': 'חינוך ומדע',
  'culture': 'תרבות',
  'legislative': 'ציבורי וכנסת',
  'business': 'כלכלה ועסקים',
  'lifestyle': 'לייף סטייל'
};

class OtaM3UParser {
  constructor() {
    this.channels = [];
    this.categories = [];
    this.categoryMap = new Map();
    this.epgUrl = '';
    this.epgUrls = [];
  }

  /**
   * Parse M3U content string
   * @param {string} content
   * @param {Object} sourceMeta Optional { id, name, url } for Multi-M3U playlists
   */
  parse(content, sourceMeta) {
    if (!content || typeof content !== 'string') {
      return { channels: [], categories: [], epgUrl: '', epgUrls: [] };
    }

    const srcId = (sourceMeta && sourceMeta.id) ? sourceMeta.id : 'src_default';
    const srcName = (sourceMeta && sourceMeta.name) ? sourceMeta.name : 'פלייליסט ראשי';
    const srcUrl = (sourceMeta && sourceMeta.url)
      ? sourceMeta.url
      : typeof sourceMeta === 'string'
      ? sourceMeta
      : '';

    const channels = [];
    const categorySet = new Set();
    const categoryMap = new Map();
    const discoveredEpgSet = new Set();

    // 2. If source URL itself is an Xtream Codes get.php URL, auto-derive xmltv.php URL
    const xtreamFromSource = this.deriveXtreamEpgUrl(srcUrl);
    if (xtreamFromSource) {
      discoveredEpgSet.add(xtreamFromSource);
    }

    let currentItem = null;
    let channelNumber = 1;
    let lineIndex = 0;
    let pos = 0;
    const len = content.length;

    while (pos < len) {
      let nl = content.indexOf('\n', pos);
      if (nl === -1) nl = len;
      const rawLine = content.slice(pos, nl);
      pos = nl + 1;

      const line = rawLine.trim();
      const currentLineIdx = lineIndex++;
      if (!line) continue;

      const firstChar = line.charCodeAt(0);
      if (firstChar === 35) { // '#'
        // 1. Scan first 30 lines for header EPG attributes
        if (currentLineIdx < 30 && line.indexOf('=') !== -1) {
          HEADER_EPG_ATTR_REGEX.lastIndex = 0;
          let match;
          while ((match = HEADER_EPG_ATTR_REGEX.exec(line)) !== null) {
            const rawVal = (match[1] || match[2] || match[3] || '').trim();
            if (rawVal) {
              const parts = rawVal.split(',');
              for (let p = 0; p < parts.length; p++) {
                const candidate = parts[p].trim();
                if (candidate && (candidate.indexOf('http://') === 0 || candidate.indexOf('https://') === 0)) {
                  discoveredEpgSet.add(candidate);
                }
              }
            }
          }
        }

        if (line.indexOf('#EXTINF:') === 0) {
          currentItem = this.parseExtInf(line, channelNumber, srcId, srcName);
        } else if (line.indexOf('#EXTGRP:') === 0) {
          if (currentItem) {
            const grp = line.slice(8).trim();
            if (grp) currentItem.group = this.normalizeGroupName(grp);
          }
        }
      } else {
        // Stream URL line
        if (currentItem) {
          currentItem.url = line;
          currentItem.uid = srcId + '::' + this.hashKey(currentItem.name + '|' + line);
          currentItem.id = currentItem.uid;
          channels.push(currentItem);

          // If no EPG URL found yet, check if stream URL matches Xtream pattern
          if (discoveredEpgSet.size === 0) {
            const xtreamFromStream = this.deriveXtreamEpgFromStreamUrl(line);
            if (xtreamFromStream) {
              discoveredEpgSet.add(xtreamFromStream);
            }
          }

          const group = currentItem.group || 'טלוויזיה חיה';
          categorySet.add(group);
          let catList = categoryMap.get(group);
          if (!catList) {
            catList = [];
            categoryMap.set(group, catList);
          }
          catList.push(currentItem);

          channelNumber++;
          currentItem = null;
        }
      }
    }

    this.epgUrls = Array.from(discoveredEpgSet);
    this.epgUrl = this.epgUrls.length > 0 ? this.epgUrls[0] : '';
    this.channels = channels;
    this.categories = Array.from(categorySet);
    this.categoryMap = categoryMap;

    return {
      channels: this.channels,
      categories: this.categories,
      categoryMap: this.categoryMap,
      epgUrl: this.epgUrl,
      epgUrls: this.epgUrls
    };
  }

  deriveXtreamEpgUrl(m3uUrl) {
    if (!m3uUrl || typeof m3uUrl !== 'string') return '';
    try {
      const m = m3uUrl.match(XTREAM_GET_REGEX);
      if (!m) return '';
      const base = m[1];
      const query = m[2];
      const userMatch = query.match(XTREAM_USER_REGEX);
      const passMatch = query.match(XTREAM_PASS_REGEX);
      if (userMatch && passMatch) {
        return base + '/xmltv.php?username=' + userMatch[1] + '&password=' + passMatch[1];
      }
    } catch (e) {}
    return '';
  }

  deriveXtreamEpgFromStreamUrl(streamUrl) {
    if (!streamUrl || typeof streamUrl !== 'string') return '';
    try {
      const m = streamUrl.match(XTREAM_STREAM_REGEX);
      if (m && m[1] && m[2] && m[3]) {
        const u = m[2].toLowerCase();
        // Avoid false positives on generic paths like /hls/stream/123.m3u8
        if (u !== 'hls' && u !== 'live' && u !== 'stream' && u !== 'tv' && u !== 'play' && u !== 'channels') {
          return m[1] + '/xmltv.php?username=' + encodeURIComponent(m[2]) + '&password=' + encodeURIComponent(m[3]);
        }
      }
    } catch (e) {}
    return '';
  }

  hashKey(str) {
    let h = 5381;
    for (let i = 0; i < str.length; i++) {
      h = ((h << 5) + h) + str.charCodeAt(i);
      h = h & h;
    }
    return Math.abs(h).toString(36);
  }

  parseExtInf(line, number, srcId, srcName) {
    const item = {
      id: srcId + '_ch_' + number,
      uid: '',
      sourceId: srcId,
      sourceName: srcName,
      originalNumber: number,
      number: number,
      name: '',
      tvgName: '',
      logo: '',
      group: 'טלוויזיה חיה',
      epgId: '',
      url: '',
      catchupType: '',
      catchupSource: '',
      catchupDays: 7
    };

    // Single-pass attribute scanner: avoids 8 separate regex scans & handles both " and ' quotes
    const len = line.length;
    let i = 8; // skip '#EXTINF:'
    let commaIndex = -1;

    while (i < len) {
      let c = line.charCodeAt(i);
      while (i < len && c <= 32) {
        c = line.charCodeAt(++i);
      }
      if (i >= len) break;
      if (c === 44) { // ','
        commaIndex = i;
        break;
      }

      const keyStart = i;
      while (i < len) {
        c = line.charCodeAt(i);
        if (c === 61 || c <= 32 || c === 44) break; // '=', whitespace, ','
        i++;
      }

      if (i < len && line.charCodeAt(i) === 61) { // '='
        const key = line.slice(keyStart, i).toLowerCase();
        i++; // skip '='
        while (i < len && line.charCodeAt(i) <= 32) i++;

        let val = '';
        if (i < len) {
          const q = line.charCodeAt(i);
          if (q === 34 || q === 39) { // '"' or "'"
            const valStart = i + 1;
            const endQ = line.indexOf(q === 34 ? '"' : "'", valStart);
            if (endQ !== -1) {
              val = line.slice(valStart, endQ).trim();
              i = endQ + 1;
            } else {
              val = line.slice(valStart).trim();
              i = len;
            }
          } else {
            const valStart = i;
            while (i < len) {
              c = line.charCodeAt(i);
              if (c <= 32 || c === 44) break;
              i++;
            }
            val = line.slice(valStart, i).trim();
          }
        }

        if (val) {
          if (key === 'group-title') {
            item.group = this.normalizeGroupName(val);
          } else if (key === 'tvg-chno' || key === 'channel-number' || key === 'ch-number') {
            const parsedNum = parseInt(val, 10);
            if (!isNaN(parsedNum) && parsedNum > 0) {
              item.number = parsedNum;
              item.originalNumber = parsedNum;
            }
          } else if (key === 'tvg-logo') {
            item.logo = val;
          } else if (key === 'tvg-name') {
            item.tvgName = val;
            if (!item.name) item.name = val;
          } else if (key === 'tvg-id' || key === 'channel-id') {
            item.epgId = val;
          } else if (key === 'catchup') {
            item.catchupType = val.toLowerCase();
          } else if (key === 'catchup-source') {
            item.catchupSource = val;
          } else if (key === 'catchup-days' || key === 'timeshift' || key === 'tvg-rec') {
            const d = parseInt(val, 10);
            if (!isNaN(d) && d > 0) {
              item.catchupDays = Math.min(7, d);
              if (!item.catchupType) {
                item.catchupType = 'flussonic';
              }
            }
          }
        }
      } else if (i < len && line.charCodeAt(i) === 44) {
        commaIndex = i;
        break;
      }
    }

    if (commaIndex !== -1) {
      const parsedName = line.slice(commaIndex + 1).trim();
      if (parsedName) {
        item.name = parsedName;
      }
    }

    if (!item.name) {
      item.name = 'ערוץ ' + number;
    }

    return item;
  }

  normalizeGroupName(rawGroup) {
    if (!rawGroup) return 'טלוויזיה חיה';
    const g = rawGroup.trim().toLowerCase();
    if (g === 'undefined' || g === 'none' || g === 'null' || g === 'uncategorized') return 'טלוויזיה חיה';
    return GROUP_NAME_MAP[g] || rawGroup;
  }
}
    /**
 * Multi-M3U Lineup Store, Custom Channel Numbering & Instant-Boot Cache Engine
 * Optimized for LG webOS 4.64 & 5.0+
 * - Supports multiple M3U playlist sources merged into one unified channel list
 * - Supports per-channel visibility selection (enabled/disabled) & custom channel numbers
 * - Caches compiled channel list in localStorage for < 20ms instant cold boot
 * - Supports 1-click sync from the PC / Mobile Web Studio (manager.html / sync-server.js)
 */
const LINEUP_KEYS = {
  SOURCES: 'zenplay_iptv_sources_v2',
  OVERRIDES: 'zenplay_iptv_channel_overrides_v2',
  CACHED_LINEUP: 'zenplay_iptv_cached_lineup_v2',
  PC_SYNC_HOST: 'zenplay_iptv_pc_sync_host',
  LEGACY_M3U: 'zenplay_iptv_m3u_url'
};

const DEFAULT_SAMPLE_M3U = 'https://iptv-org.github.io/iptv/countries/il.m3u';

class OtaLineupStore {
  constructor(parser) {
    this.parser = parser || new M3UParser();
    this.sources = [];
    this.overrides = {}; // { [channelUid]: { enabled: true/false, customNumber: 12, customName: '' } }
    this.rawChannels = []; // All parsed channels from all enabled sources
    this.compiledChannels = []; // Filtered (enabled) & sorted by customNumber
    this.discoveredEpgUrls = [];
    this._heCollator = (typeof Intl !== 'undefined' && typeof Intl.Collator === 'function')
      ? new Intl.Collator('he')
      : null;

    this.loadConfig();
  }

  loadConfig() {
    try {
      const savedSources = localStorage.getItem(LINEUP_KEYS.SOURCES);
      if (savedSources) {
        const parsed = JSON.parse(savedSources);
        if (Array.isArray(parsed) && parsed.length > 0) {
          this.sources = parsed;
        }
      }

      if (this.sources.length === 0) {
        const legacyUrl = localStorage.getItem(LINEUP_KEYS.LEGACY_M3U) || DEFAULT_SAMPLE_M3U;
        this.sources = [
          {
            id: 'src_1',
            name: 'פלייליסט ראשי (M3U #1)',
            url: legacyUrl,
            enabled: true
          }
        ];
        this.saveSources();
      }

      const savedOverrides = localStorage.getItem(LINEUP_KEYS.OVERRIDES);
      if (savedOverrides) {
        this.overrides = JSON.parse(savedOverrides) || {};
      }
    } catch (e) {
      console.warn('LineupStore loadConfig warning:', e);
      this.sources = [
        { id: 'src_1', name: 'פלייליסט ראשי', url: DEFAULT_SAMPLE_M3U, enabled: true }
      ];
      this.overrides = {};
    }
  }

  saveSources() {
    try {
      localStorage.setItem(LINEUP_KEYS.SOURCES, JSON.stringify(this.sources));
      if (this.sources.length > 0 && this.sources[0].url) {
        localStorage.setItem(LINEUP_KEYS.LEGACY_M3U, this.sources[0].url);
      }
    } catch (e) {}
  }

  saveOverrides() {
    try {
      localStorage.setItem(LINEUP_KEYS.OVERRIDES, JSON.stringify(this.overrides));
    } catch (e) {}
  }

  /**
   * Instant-Boot Cache: Returns cached compiled lineup in < 5ms so UI renders before network finishes!
   */
  loadCachedLineup() {
    try {
      const raw = localStorage.getItem(LINEUP_KEYS.CACHED_LINEUP);
      if (!raw) return null;
      const data = JSON.parse(raw);
      if (!data) return null;

      this.discoveredEpgUrls = Array.isArray(data.discoveredEpgUrls) ? data.discoveredEpgUrls : [];
      this.lastCacheTimestamp = data.updatedAt || 0;

      // Compact v2 format: stores only rawChannels (omitting empty fields) and compiles in-memory
      if (Array.isArray(data.rawChannels) && data.rawChannels.length > 0 && !Array.isArray(data.compiledChannels)) {
        this.rawChannels = data.rawChannels.map((c, idx) => {
          const seqFallback = idx + 1;
          const num = (typeof c.number === 'number' && c.number > 0) ? c.number : seqFallback;
          const defSeq = (typeof c.defaultSeqNumber === 'number' && c.defaultSeqNumber > 0) ? c.defaultSeqNumber : num;
          const origNum = (typeof c.originalNumber === 'number' && c.originalNumber > 0) ? c.originalNumber : defSeq;
          return {
            id: c.id || c.uid,
            uid: c.uid || c.id,
            sourceId: c.sourceId || 'src_default',
            sourceName: c.sourceName || '',
            originalNumber: origNum,
            defaultSeqNumber: defSeq,
            number: num,
            name: c.name || '',
            tvgName: c.tvgName || c.name || '',
            logo: c.logo || '',
            group: c.group || 'טלוויזיה חיה',
            epgId: c.epgId || '',
            url: c.url || '',
            catchupType: c.catchupType || '',
            catchupSource: c.catchupSource || '',
            catchupDays: typeof c.catchupDays === 'number' ? c.catchupDays : 7
          };
        });
        // Auto-heal if a previous cache write collapsed all channels to #1
        if (this.rawChannels.length > 2 && this.rawChannels.every((ch) => ch.number === 1)) {
          for (let i = 0; i < this.rawChannels.length; i++) {
            this.rawChannels[i].number = i + 1;
            this.rawChannels[i].defaultSeqNumber = i + 1;
            this.rawChannels[i].originalNumber = i + 1;
          }
        }
        return this.recompileLineup(true);
      }

      // Legacy format compatibility
      if (Array.isArray(data.compiledChannels) && data.compiledChannels.length > 0) {
        this.rawChannels = data.rawChannels || data.compiledChannels;
        this.compiledChannels = data.compiledChannels;
        if (this.compiledChannels.length > 2 && this.compiledChannels.every((ch) => ch.number === 1)) {
          for (let i = 0; i < this.compiledChannels.length; i++) {
            this.compiledChannels[i].number = i + 1;
          }
        }
        return this.compiledChannels;
      }
    } catch (e) {}
    return null;
  }

  isLineupCacheFresh(ttlHours) {
    if (!this.lastCacheTimestamp) return false;
    // ttlHours === 0 means manual refresh only (never auto-fetch in background)
    if (ttlHours === 0) return true;
    const ageMs = Date.now() - this.lastCacheTimestamp;
    return ageMs < ttlHours * 3600000;
  }

  clearLineupCache() {
    try {
      localStorage.removeItem(LINEUP_KEYS.CACHED_LINEUP);
      this.lastCacheTimestamp = 0;
    } catch (e) {}
  }

  compactChannelForCache(ch) {
    const out = {
      uid: ch.uid,
      sourceId: ch.sourceId,
      number: ch.number,
      name: ch.name,
      url: ch.url
    };
    if (ch.sourceName) out.sourceName = ch.sourceName;
    if (ch.originalNumber && ch.originalNumber !== ch.number) out.originalNumber = ch.originalNumber;
    if (ch.defaultSeqNumber && ch.defaultSeqNumber !== ch.number) out.defaultSeqNumber = ch.defaultSeqNumber;
    if (ch.tvgName && ch.tvgName !== ch.name) out.tvgName = ch.tvgName;
    if (ch.logo) out.logo = ch.logo;
    if (ch.group && ch.group !== 'טלוויזיה חיה') out.group = ch.group;
    if (ch.epgId) out.epgId = ch.epgId;
    if (ch.catchupType) out.catchupType = ch.catchupType;
    if (ch.catchupSource) out.catchupSource = ch.catchupSource;
    if (typeof ch.catchupDays === 'number' && ch.catchupDays !== 7) out.catchupDays = ch.catchupDays;
    return out;
  }

  saveCachedLineup() {
    this.lastCacheTimestamp = Date.now();
    // Store single compacted rawChannels copy (avoids 2x duplication) with graceful quota fallback
    const caps = [1500, 800, 400];
    for (let c = 0; c < caps.length; c++) {
      const cap = caps[c];
      try {
        const sliceLen = Math.min(this.rawChannels.length, cap);
        const compactRaw = new Array(sliceLen);
        for (let i = 0; i < sliceLen; i++) {
          compactRaw[i] = this.compactChannelForCache(this.rawChannels[i]);
        }
        const payload = {
          v: 2,
          updatedAt: this.lastCacheTimestamp,
          discoveredEpgUrls: this.discoveredEpgUrls || [],
          rawChannels: compactRaw
        };
        localStorage.setItem(LINEUP_KEYS.CACHED_LINEUP, JSON.stringify(payload));
        return;
      } catch (e) {
        if (c === caps.length - 1) {
          console.warn('Could not cache lineup in localStorage:', e);
        }
      }
    }
  }

  /**
   * Smart URL & Short-Code Normalizer:
   * - Expands 8-char Pastebin codes (e.g. "xYz123Ab" -> "https://pastebin.com/raw/xYz123Ab")
   * - Converts "pastebin.com/xYz123Ab" -> "https://pastebin.com/raw/xYz123Ab"
   * - Prepends "https://" to short links (bit.ly/..., is.gd/..., etc.)
   * - Preserves data: URLs from direct .m3u file uploads
   */
  normalizeM3uInput(rawInput) {
    const val = (rawInput || '').trim();
    if (!val) return '';
    if (val.indexOf('data:') === 0) return val;
    if (/^[a-zA-Z0-9]{8}$/.test(val)) {
      return 'https://pastebin.com/raw/' + val;
    }
    const pbMatch = val.match(/^(?:https?:\/\/)?pastebin\.com\/(?:raw\/)?([a-zA-Z0-9]+)$/i);
    if (pbMatch && pbMatch[1]) {
      return 'https://pastebin.com/raw/' + pbMatch[1];
    }
    if (val.indexOf('http://') !== 0 && val.indexOf('https://') !== 0) {
      return 'https://' + val;
    }
    return val;
  }

  /**
   * Add or update an M3U source
   */
  addSource(name, url) {
    const cleanUrl = this.normalizeM3uInput(url);
    if (!cleanUrl) return null;
    const id = 'src_' + Date.now().toString(36) + '_' + (this.sources.length + 1);
    const src = {
      id: id,
      name: (name && name.trim()) ? name.trim() : ('פלייליסט M3U #' + (this.sources.length + 1)),
      url: cleanUrl,
      enabled: true
    };
    this.sources.push(src);
    this.saveSources();
    return src;
  }

  updateSource(id, updates) {
    for (let i = 0; i < this.sources.length; i++) {
      if (this.sources[i].id === id) {
        if (typeof updates.name === 'string') this.sources[i].name = updates.name;
        if (typeof updates.url === 'string') this.sources[i].url = this.normalizeM3uInput(updates.url);
        if (typeof updates.enabled === 'boolean') this.sources[i].enabled = updates.enabled;
        this.saveSources();
        return this.sources[i];
      }
    }
    return null;
  }

  removeSource(id) {
    if (this.sources.length <= 1) {
      // If only 1 source left, clear or reset instead of leaving empty array
      return false;
    }
    this.sources = this.sources.filter((s) => s.id !== id);
    this.saveSources();

    // Clean up stale overrides belonging to the removed source
    const prefix = id + '::';
    let removedAny = false;
    const keys = Object.keys(this.overrides);
    for (let i = 0; i < keys.length; i++) {
      if (keys[i].indexOf(prefix) === 0) {
        delete this.overrides[keys[i]];
        removedAny = true;
      }
    }
    if (removedAny) {
      this.saveOverrides();
    }
    return true;
  }

  /**
   * Removes no-op overrides and (when full lineup is loaded) overrides for channels no longer present.
   */
  pruneStaleOverrides(pruneMissingUids) {
    let activeUids = null;
    if (pruneMissingUids && this.rawChannels.length > 0) {
      activeUids = new Set();
      for (let i = 0; i < this.rawChannels.length; i++) {
        if (this.rawChannels[i] && this.rawChannels[i].uid) {
          activeUids.add(this.rawChannels[i].uid);
        }
      }
    }

    let changed = false;
    const keys = Object.keys(this.overrides);
    for (let i = 0; i < keys.length; i++) {
      const uid = keys[i];
      const ov = this.overrides[uid];
      if (!ov || typeof ov !== 'object') {
        delete this.overrides[uid];
        changed = true;
        continue;
      }
      if (activeUids && !activeUids.has(uid)) {
        delete this.overrides[uid];
        changed = true;
        continue;
      }
      const isDefaultEnabled = ov.enabled !== false;
      const hasCustomNum = typeof ov.customNumber === 'number' && !isNaN(ov.customNumber) && ov.customNumber > 0;
      const hasCustomName = typeof ov.customName === 'string' && ov.customName.trim().length > 0;
      if (isDefaultEnabled && !hasCustomNum && !hasCustomName) {
        delete this.overrides[uid];
